using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Shapes;
using System.Windows.Threading;
using Forms=System.Windows.Forms;
using ClickFlow.Core;
namespace ClickFlow.Desktop;
public sealed class GuideOverlayWindow : Window
{
 private readonly IReadOnlyList<ActionStep> _steps; private readonly Canvas _canvas; private readonly DispatcherTimer _timer=new(); private readonly TextBlock _status; private int _current=-1; private readonly double _speed;
 public event Action<ActionStep>? EditRequested; public event Action<object,ActionStep>? PositionChanged;
 public GuideOverlayWindow(Window owner,IReadOnlyList<ActionStep> steps,double speedSeconds=1){Owner=owner;_steps=steps;_speed=Math.Clamp(speedSeconds,.2,10);ShowInTaskbar=false;Topmost=true;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;AllowsTransparency=true;Background=new SolidColorBrush(Color.FromArgb(205,12,20,32));var b=Forms.SystemInformation.VirtualScreen;Left=b.Left;Top=b.Top;Width=b.Width;Height=b.Height;_canvas=new Canvas();Content=_canvas;var p=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(18)};p.Children.Add(new TextBlock{Text="步骤点位引导",Foreground=Brushes.White,FontSize=20,FontWeight=FontWeights.SemiBold,VerticalAlignment=VerticalAlignment.Center});_status=new TextBlock{Foreground=Brushes.LightGray,Margin=new Thickness(18,4,18,0),VerticalAlignment=VerticalAlignment.Center};p.Children.Add(_status);var play=new Button{Content="▶ 播放",Padding=new Thickness(12,6,12,6),Margin=new Thickness(8,0,0,0)};play.Click+=(_,_)=>Play();p.Children.Add(play);var speed=new ComboBox{Width=110,Margin=new Thickness(8,0,0,0),ItemsSource=new[]{"0.5 秒/点","1 秒/点","2 秒/点","3 秒/点","5 秒/点"},SelectedIndex=SpeedIndex(_speed)};speed.SelectionChanged+=(_,_)=>{if(speed.SelectedItem is string s&&double.TryParse(s.Split(' ')[0],out var v))_timer.Interval=TimeSpan.FromSeconds(v);};p.Children.Add(speed);var close=new Button{Content="关闭 Esc",Padding=new Thickness(12,6,12,6),Margin=new Thickness(8,0,0,0)};close.Click+=(_,_)=>Close();p.Children.Add(close);var header=new Border{Background=new SolidColorBrush(Color.FromArgb(245,15,23,36)),CornerRadius=new CornerRadius(14),Child=p,Padding=new Thickness(10,8,10,8)};Canvas.SetLeft(header,24);Canvas.SetTop(header,24);_canvas.Children.Add(header);Draw(b);_timer.Interval=TimeSpan.FromSeconds(_speed);_timer.Tick+=(_,_)=>Next();PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape)Close();};Loaded+=(_,_)=>Focus();}
 static int SpeedIndex(double v)=>v<=.5?0:v<=1?1:v<=2?2:v<=3?3:4; IEnumerable<ActionStep> Points=>_steps.Where(s=>s.Enabled&&!s.UseCurrentPosition&&s.Kind is ActionKind.Click or ActionKind.DoubleClick or ActionKind.Move or ActionKind.Scroll or ActionKind.MouseDown or ActionKind.MouseUp);
 void Draw(System.Drawing.Rectangle b){var pts=Points.ToList();var i=0;foreach(var step in pts){i++;var g=new Canvas{Width=150,Height=150,Tag=step,Background=Brushes.Transparent,ToolTip="双击编辑，拖动修改位置："+step.Name};var dragging=false;g.AddHandler(UIElement.PreviewMouseLeftButtonDownEvent,new MouseButtonEventHandler((_,e)=>{if(e.ClickCount==2)EditRequested?.Invoke(step);else{dragging=true;g.CaptureMouse();_current=pts.IndexOf(step);Highlight();}e.Handled=true;}),true);g.MouseMove+=(_,e)=>{if(!dragging)return;var p=e.GetPosition(_canvas);Canvas.SetLeft(g,p.X-75);Canvas.SetTop(g,p.Y-75);};g.MouseLeftButtonUp+=(_,e)=>{if(!dragging)return;dragging=false;g.ReleaseMouseCapture();var p=e.GetPosition(_canvas);step.X=(int)Math.Round(p.X+b.Left);step.Y=(int)Math.Round(p.Y+b.Top);PositionChanged?.Invoke(this,step);e.Handled=true;};var ring=new Ellipse{Width=18,Height=18,Stroke=Brushes.White,StrokeThickness=2,Fill=new SolidColorBrush(Color.FromArgb(120,25,200,160))};var h=new Border{Width=42,Height=2,Background=Brushes.White};Canvas.SetLeft(h,54);Canvas.SetTop(h,74);g.Children.Add(h);var v=new Border{Width=2,Height=42,Background=Brushes.White};Canvas.SetLeft(v,74);Canvas.SetTop(v,54);g.Children.Add(v);Canvas.SetLeft(ring,65);Canvas.SetTop(ring,65);g.Children.Add(ring);var label=new Border{Background=Brushes.White,CornerRadius=new CornerRadius(5),Padding=new Thickness(7,3,7,3),Child=new TextBlock{Text=$"{i}. {step.Name}",Foreground=Brushes.Black,FontWeight=FontWeights.SemiBold}};Canvas.SetLeft(label,82);Canvas.SetTop(label,57);g.Children.Add(label);Canvas.SetLeft(g,step.X-b.Left-75);Canvas.SetTop(g,step.Y-b.Top-75);_canvas.Children.Add(g);}_status.Text=$"{pts.Count} 个点位 · 双击编辑 · 拖动修改位置 · 速度 {_speed:0.#} 秒/点";}
 void Play(){_current=-1;_timer.Start();Next();} void Next(){_current++;if(_current>=Points.Count()){_timer.Stop();_current=-1;}Highlight();} void Highlight(){var gs=_canvas.Children.OfType<Canvas>().Where(c=>c.Tag is ActionStep).ToList();for(var i=0;i<gs.Count;i++)gs[i].Opacity=i==_current?1:.42;_status.Text=_current>=0&&_current<gs.Count?$"当前 {_current+1}/{gs.Count} · {((ActionStep)gs[_current].Tag!).Name}":$"{gs.Count} 个点位 · 双击编辑 · 拖动修改位置";}
}
